async (page) => {
await page.goto('http://127.0.0.1:8765/chaine');
const order=[];
for(let i=0;i<12;i++){await page.keyboard.press('Tab');order.push(await page.evaluate(()=>{const e=document.activeElement;return e.tagName+':'+e.textContent.trim().slice(0,25)+':'+getComputedStyle(e).outlineStyle}));}
await page.setViewportSize({width:390,height:844});
await page.goto('http://127.0.0.1:8765/');
const o=await page.evaluate(()=>({sw:document.documentElement.scrollWidth,cw:document.documentElement.clientWidth}));
await page.screenshot({path:'m390.png'});
const links=await page.evaluate(()=>[...document.querySelectorAll('a[href]')].map(a=>a.getAttribute('href')));
const res=[];
for(const l of [...new Set(links)]){ if(l.startsWith('#'))continue; const r=await page.request.get(new URL(l,'http://127.0.0.1:8765/').href); res.push(l+':'+r.status());}
await page.setViewportSize({width:1280,height:800});
return {order,o,res};}

